// Jobs that are not ready for billing and older than DAYS_BEFORE_REMINDER.
const DAYS_BEFORE_REMINDER = 2;
const FOLLOW_UP_STATUSES = ['PENDING', 'WAITING', 'NOT_COMPLETED'];

const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - DAYS_BEFORE_REMINDER);

const overdue = $input.all()
  .map((i) => i.json)
  .filter((r) => r.id && FOLLOW_UP_STATUSES.includes(String(r.status)))
  .filter((r) => {
    const d = new Date(String(r.date));
    return !isNaN(d) && d <= cutoff;
  })
  .sort((a, b) => String(a.date).localeCompare(String(b.date)));

// No overdue jobs -> stop here, no email today.
if (overdue.length === 0) {
  return [];
}

const lines = overdue.map((r) =>
  `- ${r.date}  ${r.unit || 'Unit ?'}  [${r.category}]  ${r.status}` +
  (r.remarks ? `  — ${r.remarks}` : '') + `\n    ${r.description}`
);

return [{ json: {
  count: overdue.length,
  report: `${overdue.length} job(s) pending follow-up (older than ${DAYS_BEFORE_REMINDER} days):\n\n` + lines.join('\n')
} }];
